window.ScripturaLexicons.BDAG_PART_0260 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-01\" data-source=\"BDAG\" data-search=\"ὅρος, ου, ὁ substantivo masculino limite; fronteira espacial ou temporal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅρος, ου, ὁ</td><td>substantivo masculino</td><td>limite; fronteira espacial ou temporal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-02\" data-source=\"BDAG\" data-search=\"ὀρύσσω verbo cavar; escavar; preparar por escavação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρύσσω</td><td>verbo</td><td>cavar; escavar; preparar por escavação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-03\" data-source=\"BDAG\" data-search=\"ὀρφανός, ή, όν adjetivo/substantivo órfão; desamparado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρφανός, ή, όν</td><td>adjetivo/substantivo</td><td>órfão; desamparado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-04\" data-source=\"BDAG\" data-search=\"ὀρχέομαι verbo depoente dançar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀρχέομαι</td><td>verbo depoente</td><td>dançar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-05\" data-source=\"BDAG\" data-search=\"ὅς, ἥ, ὅ pronome relativo/demonstrativo que; quem; o qual; este; aquele BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅς, ἥ, ὅ</td><td>pronome relativo/demonstrativo</td><td>que; quem; o qual; este; aquele</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-06\" data-source=\"BDAG\" data-search=\"ὁσάκις advérbio tantas vezes quantas; sempre que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁσάκις</td><td>advérbio</td><td>tantas vezes quantas; sempre que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-07\" data-source=\"BDAG\" data-search=\"ὅσγε pronome forma de ὅς com γέ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅσγε</td><td>pronome</td><td>forma de ὅς com γέ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-08\" data-source=\"BDAG\" data-search=\"ὅσιος, ία, ον adjetivo piedoso; santo; agradável a Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅσιος, ία, ον</td><td>adjetivo</td><td>piedoso; santo; agradável a Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-09\" data-source=\"BDAG\" data-search=\"ὁσιότης, τητος, ἡ substantivo feminino piedade; devoção; santidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁσιότης, τητος, ἡ</td><td>substantivo feminino</td><td>piedade; devoção; santidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-10\" data-source=\"BDAG\" data-search=\"ὁσίως advérbio piedosamente; devotamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁσίως</td><td>advérbio</td><td>piedosamente; devotamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-11\" data-source=\"BDAG\" data-search=\"ὀσμή, ῆς, ἡ substantivo feminino cheiro; odor; perfume BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀσμή, ῆς, ἡ</td><td>substantivo feminino</td><td>cheiro; odor; perfume</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-12\" data-source=\"BDAG\" data-search=\"ὅσος, η, ον pronome correlativo quanto; tão grande quanto; todos quantos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅσος, η, ον</td><td>pronome correlativo</td><td>quanto; tão grande quanto; todos quantos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-13\" data-source=\"BDAG\" data-search=\"ὅσπερ pronome forma de ὅς com περ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅσπερ</td><td>pronome</td><td>forma de ὅς com περ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-14\" data-source=\"BDAG\" data-search=\"ὀστέον, ου substantivo neutro osso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀστέον, ου</td><td>substantivo neutro</td><td>osso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-15\" data-source=\"BDAG\" data-search=\"ὅστις, ἥτις, ὅ τι pronome relativo/interrogativo quem quer que; qualquer que; qual; por que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅστις, ἥτις, ὅ τι</td><td>pronome relativo/interrogativo</td><td>quem quer que; qualquer que; qual; por que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-16\" data-source=\"BDAG\" data-search=\"ὀστράκινος, η, ον adjetivo feito de barro ou argila; frágil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀστράκινος, η, ον</td><td>adjetivo</td><td>feito de barro ou argila; frágil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-17\" data-source=\"BDAG\" data-search=\"ὄστρακον, ου, τό substantivo neutro argila cozida; caco de cerâmica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄστρακον, ου, τό</td><td>substantivo neutro</td><td>argila cozida; caco de cerâmica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-18\" data-source=\"BDAG\" data-search=\"ὄσφρησις, εως, ἡ substantivo feminino olfato; órgão do olfato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄσφρησις, εως, ἡ</td><td>substantivo feminino</td><td>olfato; órgão do olfato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-19\" data-source=\"BDAG\" data-search=\"ὀσφῦς substantivo feminino lombos; cintura; descendência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀσφῦς</td><td>substantivo feminino</td><td>lombos; cintura; descendência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0260-20\" data-source=\"BDAG\" data-search=\"ὅταν partícula temporal quando; sempre que; visto que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅταν</td><td>partícula temporal</td><td>quando; sempre que; visto que</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0260-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores), limite, fronteira espacial: <span class=\"greek\">τ</span>. <span class=\"greek\">θάλασσαν</span> <span class=\"greek\">ἰδίοις</span> <span class=\"greek\">ὅροις</span> <span class=\"greek\">ἐνέκλεισεν</span>, encerrou o mar dentro de seus próprios limites, Dg 7:2 (Arrian, Anab. 5, 26, 2 <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ὅρους</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐποίησε</span>). De tempo: <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅρος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐτῶν</span>, limite dos anos, conclusão de Mk no manuscrito Freer 7.—DELG. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρύσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρύσσω</span>, futuro, 2ª e 3ª pessoas singulares, <span class=\"greek\">ὀρύξεις</span> e -<span class=\"greek\">ει</span>, LXX; 1º aoristo <span class=\"greek\">ὤρυξα</span>; 2º aoristo passivo <span class=\"greek\">ὠρύγην</span> (Hs 9, 6, 7; ver OGI 672, 7; 673, 6 <span class=\"greek\">ὠρύγη</span>; POxy 121, 8 <span class=\"greek\">ὀρυγῆναι</span>; Ps 93:13; En 98:13; Joseph.; Just., D. 97, 4). ① Soltar material cavando, com ênfase na própria ação, cavar, escavar <span class=\"greek\">τὶ</span>, algo; <span class=\"greek\">γῆν</span> (cf. Pla., Euthyd. 288e; Achmes 94, 14), terra, para esconder algo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:18</a>. Passiva: <span class=\"greek\">ὠρύγη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πεδίον</span>, a planície foi escavada e encontraram-se …, Hs 9, 6, 7. ② Preparar um lugar para algo cavando, escavar, preparar mediante escavação, <span class=\"greek\">τὶ</span>, algo (X., Cyr. 7, 3, 5; Diod S 1, 50, 5; Gen 26:21, 25; Jos., Ant. 8, 341; TestSol; TestZeb 2:7; ApcMos 40): <span class=\"greek\">ληνόν</span>, lagar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>. Também <span class=\"greek\">ὑπολήνιον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a> (cf. Is 5:2). <span class=\"greek\">βόθρον</span> <span class=\"greek\">θανάτου</span>, cova da morte, 11:2 (cf. Jer 2:13 e, para <span class=\"greek\">ὀρ</span>. <span class=\"greek\">βόθρ</span>., Eccl 10:8; Pr 26:27). ③ Fazer uma abertura em algo por escavação, cavar (um buraco) (X., Oec. 19, 2): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span>, na terra (isto é, para esconder <span class=\"greek\">τὸ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">τάλαντον</span>, o único talento), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:18</a>, variante de leitura.—B. 497. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρφανός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo/substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρφανός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (cf. latim orbus, «privado [de]»; em diversos sentidos ligados à perda de uma relação, Hom. e outros). ① Relativo à privação dos pais, sem pais, órfão (assim Hom. e posteriores; inscrições [New Docs 4, 162–64, com textos relativos à perda de apenas um dos pais], papiros, LXX; JosAs 12:11 [frequentemente no códice A: p. 53, 16; 55, 15 Bat.]; Philo; Jos., Ant. 18, 314 e outros), empregado nesse sentido em nossa literatura somente como substantivo (como Pla., Leg. 6, 766c; 11, 926c, e outros; papiros, LXX, TestJob, Ar., Just., Tat.), no singular e plural: órfão(s), sobretudo agrupado com <span class=\"greek\">χήρα</span> (ou <span class=\"greek\">χῆραι</span>), como pessoas que tipicamente necessitam de proteção (Liban., Or. 62 p. 379, 2 F. <span class=\"greek\">χήρας</span> <span class=\"greek\">οἰκτείρων</span>, <span class=\"greek\">ὀρφανοὺς</span> <span class=\"greek\">ἐλεῶν</span>; PCairMasp 6 anverso, 2; 2 Macc 3:10; Just., A I, 67, 6; frequentemente na LXX, mas, mais comumente, no singular desde Ex 22:22, <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">χήραν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὀρφανόν</span>): <span class=\"greek\">ἐπισκέπτεσθαι</span> <span class=\"greek\">ὀρφανοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χήρας</span>, visitar órfãos e viúvas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>; Hs 1:8. <span class=\"greek\">διαρπάζειν</span> <span class=\"greek\">χηρῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀρφανῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζωήν</span>, roubar o sustento de viúvas e órfãos, 9, 26, 2. <span class=\"greek\">κατεσθίειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">οἰκίας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χηρῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀρφανῶν</span>, devorar as casas das viúvas e dos órfãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>, variante de leitura; <span class=\"greek\">νουθετεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χήρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὀρ</span>., instruir as viúvas e os órfãos, Hv 2, 4, 3. Com <span class=\"greek\">χῆραι</span> e <span class=\"greek\">ὑστερούμενοι</span>, m 8:10; no singular Hs 5, 3, 7. Com <span class=\"greek\">χήρα</span> e <span class=\"greek\">πένης</span>, Pol 6:1. Com <span class=\"greek\">χήρα</span> e outros necessitados, ISm 6:2. Coletivamente: <span class=\"greek\">κρίνειν</span> <span class=\"greek\">ὀρφανῷ</span>, assegurar que seja feita justiça ao órfão, 1 Cl 8:4 (Is 1:17). <span class=\"greek\">χήρᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀρφανῷ</span> <span class=\"greek\">προσέχειν</span>, cuidar da viúva e do órfão, 20:2. ② Relativo à condição de quem não recebe a ajuda e o consolo de alguém que é companheiro e amigo, desamparado, órfão, extensão figurada de 1: Jesus diz aos discípulos que, depois de sua partida, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀφήσω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ὀρφανούς</span>, «não vos deixarei órfãos» (ou «como órfãos»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:18</a> (para esse uso, ver Pla., Phd. 65, 116a, onde se descrevem os sentimentos dos amigos de Sócrates: <span class=\"greek\">ἀτεχνῶς</span> <span class=\"greek\">ἡγούμενοι</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">στερηθέντες</span> <span class=\"greek\">διάξειν</span> <span class=\"greek\">ὀρφανοὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἔπειτα</span> <span class=\"greek\">βίον</span>, «pensando que passaríamos o resto da vida como filhos privados de seu pai». Semelhantemente os seguidores de Peregrinus em Lucian, Peregr. 6. Cf. Epict. 3, 24, 14; 15).—B. 130. RE VI/1, 224–25. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀρχέομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀρχέομαι</span>, depoente médio, imperfeito <span class=\"greek\">ὠρχούμην</span>; 1º aoristo <span class=\"greek\">ὠρχησάμην</span> (Hom. e posteriores; LXX; TestAbr A 10 p. 87, 23 [Stone p. 22]; Jos., Ant. 7, 87), dançar (o verbo por si mesmo não indica um tipo ou estilo específico de dança); sobre dança efetiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:22</a> (sobre a dança da filha de Herodias, ver referências citadas por Wetstein; ver ainda GDalman, PJ 14, 1918, 44–46, e o artigo <span class=\"greek\">Ἰωάννης</span> 1.—FWeege, D. Tanz in d. Antike 1926); Hs 9, 11, 5. Sobre crianças brincando (com <span class=\"greek\">αὐλεῖν</span>; cf. Aesop, Fab. 27 H.=11 P.; H-H. //24 Ch. <span class=\"greek\">ὅτε</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ηὔλουν</span>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὠρχεῖσθε</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:32</a>.—B. 689. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅς, ἥ, ὅ</h1><div class=\"entry-meta\"><span>pronome relativo/demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅς</span>, <span class=\"greek\">ἥ</span>, <span class=\"greek\">ὅ</span>. ① Como pronome relativo, quem, que, o qual, aquilo que (Hom. e posteriores). Sobre seu emprego, ver B-D-F § 293 –97; 377–80; Rydbeck 98–118; W-S. §24; Rob. 711–26; e, sobre o grego antigo em geral, Kühner-G. II 399ff; Schwyzer II 639–41. ⓐ Como regra geral, o relativo concorda em gênero e número com o substantivo ou pronome a que se refere (isto é, seu antecedente); seu caso é determinado pelo verbo, substantivo ou preposição que o rege: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀστήρ</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">εἶδον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span>, <span class=\"greek\">ὅν</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">καταγγέλλω</span> <span class=\"greek\">ὑμῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:3</a>. <span class=\"greek\">Ἰουδαῖον</span>, <span class=\"greek\">ᾧ</span> (subentenda-se <span class=\"greek\">ἦν</span>) <span class=\"greek\">ὄνομα</span> <span class=\"greek\">Βαριησοῦς</span>, 13:6. <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰουδαῖος</span> …, <span class=\"greek\">οὗ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔπαινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:29</a>. <span class=\"greek\">Ἰσραηλίτης</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">δόλος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:47</a>. <span class=\"greek\">οὗτος</span>, <span class=\"greek\">περὶ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἀκούω</span> <span class=\"greek\">τοιαῦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:9</a>, e muitíssimas vezes. ⓑ Um pronome demonstrativo frequentemente está implícito no pronome relativo: <span class=\"greek\">α</span>. de tal modo que ambos os pronomes apresentam o mesmo caso: <span class=\"greek\">ὅς</span>, aquele que; <span class=\"greek\">ὅς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">λαμβάνει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:38</a>; semelhantemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:9</a>; 9:40 (os três com condição implícita). <span class=\"greek\">οὗ</span>, daquele cujo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:26</a>. <span class=\"greek\">ᾧ</span>, àquele a quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:16</a>. <span class=\"greek\">ὅν</span>, aquele a quem (ou semelhante), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:45</a>. <span class=\"greek\">οἷς</span>, àqueles para quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:23</a>. <span class=\"greek\">οὕς</span>, aqueles a quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:21</a>. <span class=\"greek\">ὅ</span>, aquilo que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:27</a>.—Uma preposição que rege o relativo pertence em certas passagens somente ao demonstrativo (omitido): <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὅ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:8</a>; <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὅ</span> (<span class=\"greek\">ἅ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:6</a>; Phlm 21; <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἅ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:29</a>. Em outras, deve ser acrescentada a ambos os pronomes: <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, naquilo em que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:12</a>; 3:16 (essas passagens de 1 Pt também podem ser classificadas sob 1k <span class=\"greek\">γ</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:11</a>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">οὑ</span>, por causa daquilo pelo que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:30</a>. <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὧν</span>, das pessoas de quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:3</a>.—A muito discutida passagem <span class=\"greek\">ἑταῖρε</span>, <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">πάρει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a>, pertenceria aqui se supríssemos as palavras necessárias para ler aproximadamente: «amigo, (estás utilizando indevidamente o beijo) para aquele (propósito) pelo qual vieste?» (Wlh.; EKlostermann); ou: «em relação àquilo (= aos propósitos) para cuja realização apareceste (tu me beijas)?» (Rdm. 2 78). «Amigo, vieste para esse propósito?» FRehkopf, ZNW 52, ’61, 109–15. Mas ver <span class=\"greek\">β</span> <span class=\"hebrew\" dir=\"rtl\">ב</span> e i <span class=\"greek\">β</span> abaixo. <span class=\"greek\">β</span>. Contudo, os dois pronomes também podem apresentar casos diferentes; nessas situações o demonstrativo quase sempre está no nominativo ou acusativo. <span class=\"hebrew\" dir=\"rtl\">א</span>. No nominativo: <span class=\"greek\">οὗ</span>, aquele cujo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:25</a>. <span class=\"greek\">ὧν</span>, aqueles cujos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:7</a> (Ps 31:1). <span class=\"greek\">ᾧ</span>, aquele a quem ou para quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:9</a>. <span class=\"greek\">οἷς</span>, aqueles a quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:21</a> (Is 52:15). <span class=\"greek\">ὅ</span>, aquilo (nominativo) que (acusativo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:12</a>; 25:29; 26:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a>. Semelhantemente <span class=\"greek\">ἅ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:20</a>. <span class=\"greek\">ὅν</span>, aquele a quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:34</a>; 4:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:21</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅν</span>, aquele acerca do qual, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:13</a>. <span class=\"hebrew\" dir=\"rtl\">ב</span>. No acusativo: <span class=\"greek\">ὧν</span>, as coisas de que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:29</a>. <span class=\"greek\">ᾧ</span>, aquele (em) quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:12</a>. Também com preposição: <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, qualquer coisa pela qual, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span>, coisas nas quais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:12</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅ</span>, aquilo sobre o que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:25</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span>, as coisas acerca das quais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:13</a>. <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span>, das coisas das quais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:21</a> (essa passagem talvez empregue metáfora comercial; sobre os papiros, ver Mayser II/2, 434f §121). <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span>, aquele em quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14a</a>.—Assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a> (ver b <span class=\"greek\">α</span> acima), se as palavras a suprir forem aproximadamente: «amigo, (faz aquilo) para o que vieste!» (assim ESchwartz, ByzZ 25, 1925, 154f; EOwen, JTS 29, 1928, 384–86; WSpiegelberg, ZNW 28, 1929, 341–43; FZorell, VD 9, 1929, 112–16; semelhantemente PMaas, Byz.-Neugriech. Jahrb. 8, ’31, 99; 9, ’32, 64; WEltester: OCullmann Festschr., ’62, 70–91; mas ver i <span class=\"greek\">β</span>, final.—Ver Jos., Bell. 2, 615 sob <span class=\"greek\">πάρειμι</span> 1a). <span class=\"hebrew\" dir=\"rtl\">ג</span>. Somente em exemplos isolados o demonstrativo a suprir aparece em outro caso: <span class=\"greek\">οὗ</span> = <span class=\"greek\">τούτῳ</span>, <span class=\"greek\">οὗ</span>, nele de quem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14b</a>. <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὧν</span> = <span class=\"greek\">τούτοις</span>, <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὧν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:34</a>. ⓒ Construções peculiares em algum aspecto. <span class=\"greek\">α</span>. O emprego pleonástico do pronome pessoal após <span class=\"greek\">ὅς</span> (Mlt. 94f; B-D-F § 297): <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θυγάτριον</span> <span class=\"greek\">αὐτῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:25</a>, encontra-se no grego mais antigo (Hyperid., Euxen. 3 <span class=\"greek\">ὧν</span> … <span class=\"greek\">τούτων</span>.—Kühner-G. II 433f), não é desconhecido no grego posterior (POxy 117, 15), mas sobretudo é sugerido pelas línguas semíticas (LXX; GrBar 2:1; Thackeray 46; JHudson, ET 53, ’41/42, 266f); a omissão de <span class=\"greek\">αὐτῆς</span> na variante de leitura está de acordo com o uso grego. <span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πτύον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χειρὶ</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:17</a>. <span class=\"greek\">οὗ</span> … <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑποδημάτων</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>. <span class=\"greek\">οὗ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μώλωπι</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:24</a>, variante de leitura. <span class=\"greek\">οὗ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">συγγράματα</span>, EpilMosq 2. Numa citação: <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οὓς</span> <span class=\"greek\">ἐπικέκληται</span> … <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:17</a> = Am 9:12. <span class=\"greek\">οὗ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πνοὴ</span> <span class=\"greek\">αὐτοῦ</span>, 1 Cl 21:9. Especialmente frequente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:8</a>; 7:2, 9; 9:11, variante de leitura; 13:8, 12; 20:8. <span class=\"greek\">β</span>. Construções «ad sensum» <span class=\"hebrew\" dir=\"rtl\">א</span>. Um relativo singular refere-se a algo no plural: <span class=\"greek\">οὐρανοῖς</span> … <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὗ</span> (<span class=\"greek\">οὐρανοῦ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:20</a>. <span class=\"hebrew\" dir=\"rtl\">ב</span>. Um relativo plural refere-se a um antecedente singular (Jdth 4:8 <span class=\"greek\">γερουσία</span>, <span class=\"greek\">οἵ</span>): <span class=\"greek\">πλῆθος</span> <span class=\"greek\">πολύ</span> …, <span class=\"greek\">οἳ</span> <span class=\"greek\">ἦλθον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17f</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">πᾶσαν</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">αἷς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:36</a>. Cf. <span class=\"greek\">ἤδη</span> <span class=\"greek\">δευτέραν</span> <span class=\"greek\">ἐπιστολήν</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">αἷς</span> (isto é, <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">δυσὶν</span> <span class=\"greek\">ἐπιστ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:1</a>. <span class=\"hebrew\" dir=\"rtl\">ג</span>. O relativo concorda com o gênero natural, em vez do gênero gramatical do substantivo antecedente: <span class=\"greek\">τέκνα</span> <span class=\"greek\">μου</span>, <span class=\"greek\">οὕς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a>; cf. 2 J 1; Phlm 10. <span class=\"greek\">ἔθνη</span>, <span class=\"greek\">οἵ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:17</a> (Am 9:12); cf. 26:17. <span class=\"greek\">παιδάριον</span>, <span class=\"greek\">ὅς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a>. <span class=\"greek\">θηρίον</span>, <span class=\"greek\">ὅς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:14</a>. <span class=\"greek\">ὀνόματα</span>, <span class=\"greek\">οἵ</span>, 3:4, variante de leitura. <span class=\"greek\">γενεᾶς</span> <span class=\"greek\">σκολιᾶς</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:15</a>. Em referência a Cristo, <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>, <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὗ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:19</a>. ⓓ Atração (ou assimilação) do relativo. Como em Hdt., frequentemente no ático, nas inscrições, nos papiros e na LXX, o relativo simples <span class=\"greek\">ὅς</span>, <span class=\"greek\">ἥ</span>, <span class=\"greek\">ὅ</span> às vezes é atraído para o caso do antecedente, embora sua função na oração própria exigisse outro caso. <span class=\"greek\">α</span>. Na maioria das ocorrências, o acusativo do relativo é atraído para o genitivo ou dativo do antecedente: <span class=\"greek\">περὶ</span> <span class=\"greek\">πράγματος</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">αἰτήσωνται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:19</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">διαθήκης</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">διέθετο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:25</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:50b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:20</a>; 3:19; 5:9; 9:43; 15:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:14</a>; 7:31; 15:20; 17:5; 21:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:1</a>; 2:22; 22:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:6</a>; 10:8, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:4</a>; Jd 15 e outros.—Quando o antecedente é um demonstrativo subentendido, mas não expresso (ver b, início), que estaria no genitivo ou no dativo, o acusativo do relativo pode ser atraído a esse genitivo ou dativo: <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἑώρακαν</span> equivale propriamente a <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἑώρακαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:36</a> (Schwyzer II 641); <span class=\"greek\">ἅ</span> adquire o caso de <span class=\"greek\">τούτων</span>, o qual, por sua vez, é omitido (assim já em Soph., Pla. e outros).—23:14, 41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a>; 21:19, 24; 22:15; 25:11; 26:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:8</a>. <span class=\"greek\">ὧν</span> = <span class=\"greek\">τούτων</span>, <span class=\"greek\">οὕς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:17</a>. <span class=\"greek\">οἷς</span> = <span class=\"greek\">τούτοις</span>, <span class=\"greek\">ἅ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:25</a>. <span class=\"greek\">β</span>. O dativo do relativo é atraído com menor frequência (B-D-F § 294, 2; Rob. 717): <span class=\"greek\">ἕως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἧς</span> (= <span class=\"greek\">ᾗ</span>) <span class=\"greek\">ἀνελήμφθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:22</a> (cf. Lev 23:15; 25:50; Bar 1:19); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:6</a>; 4:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:6</a>, variante de leitura; <span class=\"greek\">κατέναντι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐπίστευσεν</span> <span class=\"greek\">θεοῦ</span> = <span class=\"greek\">κατέν</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐπίστ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:17</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρακλήσεως</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">παρακαλούμεθα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:4</a>. <span class=\"greek\">γ</span>. Nas orações relativas compostas de sujeito, predicativo e cópula, o relativo às vezes concorda em gênero e número não com o substantivo a que se refere, mas com o predicativo, caso seja sujeito; e, inversamente, com o sujeito, caso seja predicativo em sua própria oração: <span class=\"greek\">πνεύματι</span> …, <span class=\"greek\">ὅς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀρραβών</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:14</a>, variante de leitura. <span class=\"greek\">τῷ</span> <span class=\"greek\">σπέρματί</span> <span class=\"greek\">σου</span>, <span class=\"greek\">ὅς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">Χριστός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:16</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">μάχαιραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:17</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:5</a>; 5:8. <span class=\"greek\">δ</span>. A atração inversa ocorre quando o relativo atrai seu antecedente para o próprio caso (desde Hom.; também Soph., Oed. Rex 449; ver Kühner-G. II 413; Schwyzer II 641; B-D-F § 295; Rob. 717f): <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρτον</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">κλῶμεν</span>, <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">κοινωνία</span> … <span class=\"greek\">ἐστιν</span>; = <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄρτος</span> <span class=\"greek\">ὅν</span> …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a>. <span class=\"greek\">λίθον</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἀπεδοκίμασαν</span> … <span class=\"greek\">οὗτος</span> <span class=\"greek\">ἐγενήθη</span> (Ps 117:22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a>, variante de leitura.—<span class=\"greek\">παντὶ</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">πολύ</span>, <span class=\"greek\">πολὺ</span> <span class=\"greek\">ζητηθήσεται</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:48</a>. <span class=\"greek\">ὅρκον</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ὤμοσεν</span> (= <span class=\"greek\">μνησθῆναι</span> <span class=\"greek\">ὅρκου</span> <span class=\"greek\">ὅν</span>), 1:73 (ver W-S. §24, 7, nota). <span class=\"greek\">τοὺς</span> <span class=\"greek\">λίθους</span>, <span class=\"greek\">οὓς</span> <span class=\"greek\">εἶδες</span>, <span class=\"greek\">ἀποβεβλημένους</span>, <span class=\"greek\">οὗτοι</span> … <span class=\"greek\">ἐφόρεσαν</span>, Hs 9, 13, 3. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:25</a>. <span class=\"greek\">ε</span>. A atração pode deixar de ocorrer, como no grego mais antigo (Thu. 2, 70, 4), quando a oração relativa está mais nitidamente separada do antecedente por modificadores adicionais do substantivo e pela importância do conteúdo da própria oração relativa (B-D-F § 294, 1; Rob. 714f): <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθινῆς</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">ἔπηξεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἄνθρωπος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:2</a>. Ver também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:22</a>; 4:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:2</a>; Phlm 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:20</a>. ⓔ O substantivo antecedente da oração relativa pode ser incorporado nesta. <span class=\"greek\">α</span>. Sem abreviar a construção nem atrair o caso: <span class=\"greek\">ᾗ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δοκεῖτε</span> <span class=\"greek\">ὥρᾳ</span> = <span class=\"greek\">τῇ</span> <span class=\"greek\">ὥρᾳ</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δοκ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:44</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:40</a>; 17:29, 30. <span class=\"greek\">ἃ</span> <span class=\"greek\">ἡτοίμασαν</span> <span class=\"greek\">ἀρώματα</span>, 24:1. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">σημεῖον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:14</a>. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">θέλω</span> <span class=\"greek\">ἀγαθόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:19</a>. <span class=\"greek\">β</span>. Com abreviação, quando uma preposição normalmente repetida é usada só uma vez: <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">κρίματι</span> <span class=\"greek\">κρίνετε</span> <span class=\"greek\">κριθήσεσθε</span> = <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρίματι</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">κρίνετε</span>, <span class=\"greek\">κριθήσεσθε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:2a</a>. Cf. versículo 2b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:24</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τόπῳ</span> = <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἦν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:6</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τρόπον</span> = <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τρόπον</span>, <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:11</a>. <span class=\"greek\">γ</span>. Com mudança de caso, sobretudo por atração. <span class=\"hebrew\" dir=\"rtl\">א</span>. Do pronome relativo: <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">πονηρῶν</span> = <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">πονηρῶν</span>, <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐπ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:19</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">πασῶν</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">εἶδον</span> <span class=\"greek\">δυνάμεων</span> = <span class=\"greek\">περὶ</span> <span class=\"greek\">πασῶν</span> <span class=\"greek\">δυνάμεων</span>, <span class=\"greek\">ἃς</span> <span class=\"greek\">εἶδον</span>, 19:37. <span class=\"greek\">αἰτίαν</span> … <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὑπενόουν</span> <span class=\"greek\">πονηρῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:18</a>.—O dativo do relativo também é atraído a outros casos: <span class=\"greek\">ἄχρι</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">ἡμέρας</span> = <span class=\"greek\">ἄχρι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>, <span class=\"greek\">ᾖ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>; 17:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:2</a>. <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">ἡμέρας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:6</a>, 9. <span class=\"hebrew\" dir=\"rtl\">ב</span>. Do substantivo a que o relativo se refere: <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἀπεκεφάλισα</span> <span class=\"greek\">Ἰωάννην</span>, <span class=\"greek\">οὗτος</span> <span class=\"greek\">ἠγέρθη</span> = <span class=\"greek\">Ἰωάννης</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">κτλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:16</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">παρεδόθητε</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">διδαχῆς</span> = <span class=\"greek\">τῷ</span> <span class=\"greek\">τύπῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διδαχῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">παρεδόθητε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:17</a>. <span class=\"greek\">δ</span>. A análise é duvidosa em passagens como <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">κατηχήθης</span> <span class=\"greek\">λόγων</span> = <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">οὓς</span> <span class=\"greek\">κατηχήθης</span> ou <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span>, <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">κατηχήθης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:4</a>. <span class=\"greek\">ἄγοντες</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ᾧ</span> <span class=\"greek\">ξενισθῶμεν</span> <span class=\"greek\">Μνάσωνι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:16</a>, segundo o sentido, deve equivaler a <span class=\"greek\">ἄγοντες</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Μνάσωνα</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">ξενισθῶμεν</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῷ</span>. Ver B-D-F § 294, 5; Rob. 719. ⓕ A preposição pode ser omitida antes do relativo, caso já tenha sido usada antes do substantivo antecedente: <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">χρόνῳ</span> <span class=\"greek\">ᾧ</span> (= <span class=\"greek\">ἐν</span> <span class=\"greek\">ὧ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:21</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ὅ</span> (= <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅ</span>), 13:2. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ὧν</span> (= <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὧν</span>), versículo 38. Cf. 26:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποτηρίῳ</span> <span class=\"greek\">ᾧ</span> (= <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:6</a>. ⓖ Usa-se o neutro. <span class=\"greek\">α</span>. Em explicações, especialmente de palavras estrangeiras e alegorias: <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span>, isto é, que significa: <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">Σαλήμ</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">εἰρήνης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:17</a>; 7:11, 34; 15:42. Também <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μεθερμηνευόμενον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:38</a>, 41f. <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μεθερμηνευόμενος</span> <span class=\"greek\">κρανίου</span> <span class=\"greek\">τόπος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:22</a>, variante de leitura (por <span class=\"greek\">μεθερμηνευόμενον</span>). <span class=\"greek\">τόπος</span>, <span class=\"greek\">ὸ̔</span> <span class=\"greek\">λέγεται</span>, <span class=\"greek\">Ἑβραϊστὶ</span> <span class=\"greek\">Γολγοθά</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:17</a>.—Ver também <span class=\"greek\">αὐλῆς</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">πραιτώριον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:16</a>. <span class=\"greek\">λεπτὰ</span> <span class=\"greek\">δὺο</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">κοδράντης</span>, 12:42. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:24</a>. <span class=\"greek\">πλεονέκτης</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">εἰδωλολάτρης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:5</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">σύνδεσμος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τελειότητος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:14</a>.—B-D-F § 132, 2. <span class=\"greek\">β</span>. Quando o pronome relativo retoma toda uma oração: <span class=\"greek\">τοῦτον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">ἀνέστησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <span class=\"greek\">οὗ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">μάρτυρες</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:32</a>; cf. 3:15; 11:30; 26:9f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:8</a>. <span class=\"greek\">γ</span>. <span class=\"greek\">ὅ</span> deve ser entendido como objeto acusativo cujo conteúdo é fornecido pelo que vem imediatamente depois nestas passagens (ver W-S. §24, 9; Rob. 715): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἀπέθανεν</span>, <span class=\"greek\">τῇ</span> <span class=\"greek\">ἁμαρτίᾳ</span> <span class=\"greek\">ἀπέθανεν</span> <span class=\"greek\">ἐφάπαξ</span> = <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἀπέθανεν</span> <span class=\"greek\">κτλ</span>., aquilo que morreu, isto é, a morte que sofreu, ele a sofreu pelo pecado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:10a</a>; cf. versículo 10b. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ζῶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, a vida que agora vivo na carne, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:20</a>. ⓗ O relativo é empregado com sentido consecutivo ou final (resultado ou finalidade): <span class=\"greek\">τίς</span> <span class=\"greek\">ἔγνω</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">κυρίου</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">συμβιβάσει</span> <span class=\"greek\">αὐτόν</span>;, quem conheceu a mente do Senhor, para poder instruí-lo?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:16</a> (cf. Is 40:13). <span class=\"greek\">ἄξιός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">παρέξῃ</span> <span class=\"greek\">τοῦτο</span>, ele é digno de que lhe concedas isso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:4</a>. <span class=\"greek\">ἀποστέλλω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄγγελόν</span> <span class=\"greek\">μου</span> …, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">κατασκευάσει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:10</a>. <span class=\"greek\">ἔπεμψα</span> <span class=\"greek\">Τιμόθεον</span> …, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀναμνήσει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>. <span class=\"greek\">ἔχετε</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἑαυτῶν</span>, <span class=\"greek\">εἰς</span> <span class=\"greek\">οὓς</span> <span class=\"greek\">ἐργάσεσθε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καλόν</span>, 21:2. ⓘ Substituindo pronome interrogativo. <span class=\"greek\">α</span>. Em perguntas indiretas (Soph., Oed. Rex 1068; Thu. 1, 136, 4; inscrições áticas de 411 a.C. em Meisterhans 3-Schw.; papiros [Witkowski 30, 7]; frequentemente em Joseph. [Schmidt 369]; Just., D. 44, 4 <span class=\"greek\">δι</span>’ <span class=\"greek\">ἧς</span> <span class=\"greek\">ὁδοῦ</span>): <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ποιῶ</span>, o que estou fazendo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:7</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">λέγουσιν</span>, aquilo que dizem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:7</a> (Just., D. 9, 1 <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οἶδας</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">λέγεις</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:21</a>. <span class=\"greek\">β</span>. A filologia do NT, em geral, rejeitou a hipótese de que <span class=\"greek\">ὅς</span> seja usado em perguntas diretas (Mlt. 93; B-D-F § 300, 2; Radermacher 2 78; PMaas [ver 1b <span class=\"greek\">β</span> <span class=\"hebrew\" dir=\"rtl\">ב</span> acima]). Ainda falta encontrar exemplo inequívoco desse uso. Até a inscrição num cálice publicada por Dssm., LO 100ff [LAE 125–31], ET 33, 1922, 491–93, deixa margem a dúvida. Por isso, também a tradução de <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔</span> <span class=\"greek\">πάρει</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:50</a>, como «para que estás aqui?» (assim Goodsp., Probs. 41–43; semelhantemente, já Lutero, depois Dssm.; JWilson, ET 41, 1930, 334) tem sido considerada suspeita. Ver ZNW 52, ’61, 109ff.—Rob. 725 duvida do sentido interrogativo aqui, mas Mlt-Turner 50 tende a aceitá-lo. Se forem encontradas mais provas do uso interrogativo de <span class=\"greek\">ὅς</span>, considerações de crítica literária (ver versículos 14–16) convidam a prestar atenção à variante de leitura (ver aparato de Tdf.) <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ᾦ</span>, combinação usada em documentos comerciais (PGrenf II, 17, 2; 5; Mayser II/1 p. 215); o uso coloquial sugere: «que negócio fizeste?»—Ver também 1b <span class=\"greek\">β</span> <span class=\"hebrew\" dir=\"rtl\">ב</span> acima. ⓙ Combinado com partículas. <span class=\"greek\">α</span>. Com <span class=\"greek\">ἄν</span> (<span class=\"greek\">ἐάν</span>), ver <span class=\"greek\">ἄν</span> I. b. <span class=\"greek\">β</span>. Com <span class=\"greek\">γέ</span> (ver <span class=\"greek\">γέ</span> a <span class=\"greek\">β</span> e cf. PFlor 370, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32</a>. <span class=\"greek\">γ</span>. Com <span class=\"greek\">δήποτε</span>, «qualquer que seja», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a>(4), variante de leitura (as variantes oscilam entre <span class=\"greek\">οἵῳ</span> e <span class=\"greek\">ᾧ</span>, <span class=\"greek\">δηποτοῦν</span> e <span class=\"greek\">δήποτε</span>). <span class=\"greek\">δ</span>. Com <span class=\"greek\">καί</span>, «que também», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:13f</a>; 7:49 e outros. <span class=\"greek\">ε</span>. Com <span class=\"greek\">περ</span> = <span class=\"greek\">ὅσπερ</span>, <span class=\"greek\">ἥπερ</span>, <span class=\"greek\">ὅπερ</span> (TestSol, TestAbr; TestJob 7:13; JosAs 14:12; GrBar; ApcSed 2:1; Jos., Ant. 2, 277, Vi. 95; apologistas [exceto Mel.]), precisamente aquele que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:6</a>, variante de leitura. <span class=\"greek\">ὅπερ</span>, o qual de fato, Ox 840, 35; ISm 4:1. <span class=\"greek\">πάντα</span> <span class=\"greek\">ἅπερ</span>, tudo quanto, GPt 11:45. ⓚ Usado com preposição (ver também acima 1b <span class=\"greek\">α</span>; 1b <span class=\"greek\">β</span> <span class=\"hebrew\" dir=\"rtl\">ב</span>; 1e <span class=\"greek\">β</span>,<span class=\"greek\">γ</span>; 1f, e Johannessohn, Präp. 382f [índice]), formando uma espécie de conjunção. <span class=\"greek\">α</span>. Com <span class=\"greek\">ἀντί</span>: <span class=\"greek\">ἀνθ</span>’ <span class=\"greek\">ὧν</span> (ver <span class=\"greek\">ἀντί</span> 4), porque, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>; 19:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:10</a>; por conseguinte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a>. <span class=\"greek\">β</span>. Com <span class=\"greek\">εἰς</span>: <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅ</span>, para esse fim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:11</a>. <span class=\"greek\">γ</span>. Com <span class=\"greek\">ἐν</span>: <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> liga-se à situação descrita anteriormente, «em tais circunstâncias», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:18</a>, variante de leitura; 26:12. Talvez também <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:6</a>; 2:12; 3:16, 19; 4:4. Ver também <span class=\"greek\">ἐν</span> 7 e cf. 1b <span class=\"greek\">α</span> acima. <span class=\"greek\">δ</span>. Com <span class=\"greek\">ἐπί</span>: <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ᾧ</span> (normalmente «por aquilo pelo que»: Plut., Cimon 483 [8, 6], Címon recebe honras em retribuição por sua generosidade [cf. o plural <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span>, IPriene 114, 22, acerca de honras concedidas a um ginasiarca por suas muitas contribuições]; cf. Plut., Mor. 522e e Diog. L. 7, 173. Inversamente, Plut., Aratus 1048 [44, 4]: A. sofre certa desonra «pelo que» fez a um associado), tem sido frequentemente interpretado como = <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">ὅτι</span>, pela razão de que, porque, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a> (bibliografia sob <span class=\"greek\">ἁμαρτία</span> 3a); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a>; para 4:10. Contudo, uma metáfora comercial pode estar expressa nas primeiras 3 passagens citadas; ver <span class=\"greek\">ἐπί</span> 6c. Diferentemente quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a>, JFitzmyer, NTS 39, ’93, 321–39; também comentário (Anchor) ad loc.: «com o resultado de que, de modo que». <span class=\"greek\">ε</span>. <span class=\"greek\">οὗ</span> <span class=\"greek\">χάριν</span>, por isso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:47</a>. <span class=\"greek\">ζ</span>. Em indicações temporais: <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἧς</span> (ver <span class=\"greek\">ἀπό</span> 2b <span class=\"greek\">γ</span> e cf. BGU 252, 9 [98 d.C.]), desde o tempo em que, desde que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:4</a>; Hs 8, 6, 6, variante de leitura; assim que, depois que, 8, 1, 4.—<span class=\"greek\">ἀφ</span>’ <span class=\"greek\">οὗ</span> (ver <span class=\"greek\">ἀπό</span> 2b <span class=\"greek\">γ</span>), desde que, uma vez que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:25</a>; 24:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:18</a>. <span class=\"greek\">ἄχρι</span> <span class=\"greek\">οὗ</span> (ver <span class=\"greek\">ἄχρι</span> 1b <span class=\"greek\">α</span>), até que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a>. Também <span class=\"greek\">ἕως</span> <span class=\"greek\">οὗ</span>, até que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:25</a>; 13:33; 14:22; 17:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:21</a>; D 11:6 e outros. <span class=\"greek\">μέχρις</span> <span class=\"greek\">οὗ</span>, até que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:19</a>.—Sobre o genitivo <span class=\"greek\">οὗ</span> como advérbio de lugar, consultar o verbete próprio. ② Pronome demonstrativo, este, aquele (Hom. e posteriores; prosa de Hdt. e outros [Kühner-G. II 228f]; papiros, LXX). ⓐ <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">δέ</span>, mas ele (Ps.-Lucian, Philopatris 22; PRyl 144, 14 [38 d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:11</a>, variante de leitura. Principalmente ⓑ <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">δέ</span>, um … outro (Hippocr. e posteriores; muito frequente em escritores posteriores; POxy 1189, 7 [cerca de 117 d.C.]; SibOr 3, 654), masculino em vários casos do singular e plural: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:16</a>; Jd 22f. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δέ</span>, este … aquele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:21</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἃ</span> <span class=\"greek\">δέ</span> (Lucian, Rhet. Praec. 15), uns … outros, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a>. <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">δέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:35</a>; 25:15 (Lucian, Tim. 57 <span class=\"greek\">διδοὺς</span> … <span class=\"greek\">ᾧ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">δραχμάς</span>, <span class=\"greek\">ᾧ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">μνᾶν</span>, <span class=\"greek\">ᾧ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἡμιτάλαντον</span>). <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:8b</a>, 23. <span class=\"greek\">ᾧ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλῳ</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἑτέρῳ</span> (<span class=\"greek\">ἄλλῳ</span> <span class=\"greek\">δέ</span> repete-se então cinco vezes, e antes da última ocorrência há um segundo <span class=\"greek\">ἑτέρῳ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:8</a>–10. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλο</span> <span class=\"greek\">κτλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:4</a>. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕτερον</span> (repetido várias vezes), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλα</span> <span class=\"greek\">δέ</span> (repetido várias vezes), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:4</a>–8a. Em anacoluto: <span class=\"greek\">οὓς</span> <span class=\"greek\">μέν</span>, sem <span class=\"greek\">οὓς</span> <span class=\"greek\">δέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:28</a>. <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀσθενῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:2</a>.—B-D-F § 250. MBlack, An Aramaic Approach 3, ’67, 100f.—DELG 1 <span class=\"greek\">ὅς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁσάκις</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁσάκις</span>, advérbio (em Hom., <span class=\"greek\">ὁσσάκι</span>; na forma <span class=\"greek\">ὁσάκις</span>, Lysias, Pla., X. e outros; inscrições, papiros; Jos., Vi. 160; Just.; Tat. 14, 1), tantas vezes quantas, sempre que, com <span class=\"greek\">ἐάν</span> (SIG 972, 124; BGU 1115, 22 [13 a.C.]; PHamb 37, 3; PGiss 12, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:25f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅσγε</h1><div class=\"entry-meta\"><span>pronome</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅσγε</span>, por <span class=\"greek\">ὅς</span> <span class=\"greek\">γε</span>; ver <span class=\"greek\">ὅς</span> 1j <span class=\"greek\">β</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅσιος, ία, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅσιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ον</span> (Aeschyl., Hdt. e posteriores [o substantivo <span class=\"greek\">ὁσίη</span> ocorre já em Hom.]. Predominantemente com três terminações, mas -<span class=\"greek\">ος</span>, <span class=\"greek\">ον</span>, Pla., Leg. 8, 831d; Dionys. Hal. 5, 71; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:8</a>. B-D-F § 59, 2; W-S. §11, 1; Mlt-H. 157). Superlativo <span class=\"greek\">ὁσιώτατος</span> (Pla.; OGI 718, 1; Philo; 1 Cl 58:1). No mundo greco-romano, esse termo descrevia, em grande parte, aquilo que ajuda a manter o delicado equilíbrio entre os interesses da sociedade e as expectativas do domínio transcendente. Por exemplo, a pessoa <span class=\"greek\">ὅσιος</span> ora e sacrifica aos deuses (Pl., Euthyph. 14b), tem consciência dos tabus fundamentais (por isso, evita a impureza decorrente de derramamento de sangue [ibidem 4de; cf. Od. 16, 423]) e observa as tradições de hospitalidade (sobre Zeus como protetor do estrangeiro, ver Od. 9, 270f). Sobre o contraste entre <span class=\"greek\">τὸ</span> <span class=\"greek\">ὅσιον</span> e <span class=\"greek\">τὸ</span> <span class=\"greek\">δίκαιον</span>, ver Pla., Gorgias 507b, Polit. 301d; X., Hell. 4, 1, 33 e outros. ① Relativo à ausência de culpa perante a divindade, devoto, piedoso, agradável a Deus, santo. ⓐ Sobre seres humanos comuns: com <span class=\"greek\">δίκαιος</span> (cf. Pla., Leg. 2, 663b, Gorg. 507b; Polyb. 22, 10, 8 <span class=\"greek\">παραβῆναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">δίκαια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ὅσια</span>; SIG 800, 20f: <span class=\"greek\">ἀναστρέφεται</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τε</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ὁσίως</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαίως</span>; En 104:12; TestGad 5:4; TestBenj 3:1 e 5:4; Jos., Ant. 9, 35; Just., D. 96, 3 [após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:45</a>]; Theoph. Ant. 2, 9 [p. 120, 3]), 1 Cl 45:3; 2 Cl 15:3; e ainda outras virtudes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:8</a>. <span class=\"greek\">ἔργα</span> <span class=\"greek\">ὅσια</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δίκαια</span> (Jos., Ant. 8, 245), 2 Cl 6:9. <span class=\"greek\">δίκαιον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὅσιον</span>, com acusativo e infinitivo em seguida (Dicaearchus p. 408, linha 2 a partir do rodapé, Fuhr; cf. <span class=\"greek\">ὅσιον</span> <span class=\"greek\">εἶναι</span> com acusativo e infinitivo, Orig., C. Cels. 5, 26, 13), 1 Cl 14:1. <span class=\"greek\">ὀφείλομεν</span> <span class=\"greek\">ὅσια</span>, 2 Cl 1:3. (Com <span class=\"greek\">ἄμωμος</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀμώμῳ</span> <span class=\"greek\">προθέσει</span> <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, servir a Deus com propósito santo e irrepreensível, 1 Cl 45:7. <span class=\"greek\">ἄνδρες</span>, 45:3. <span class=\"greek\">ὁς</span>. <span class=\"greek\">βουλή</span>, 2:3.—<span class=\"greek\">ὅσιοι</span> <span class=\"greek\">χεῖρες</span>, mãos santas (Aeschyl., Choëph. 378; Soph., Oed. Col. 470: «consagradas», «cerimonialmente puras»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:8</a>, transferido ao campo ético-religioso (Philip de Perg. [II d.C.]: 95 Fgm. 1 Jac. escreve <span class=\"greek\">ὁσίῃ</span> <span class=\"greek\">χειρί</span>).—O termo provavelmente era empregado em sentido cultual nos mistérios (ERohde, Psyche 9/10, 1925 I 288, 1): Aristoph., Ran. 335 <span class=\"greek\">ὅσιοι</span> <span class=\"greek\">μύσται</span>. Os iniciados nos mistérios órficos são denominados <span class=\"greek\">οἱ</span> <span class=\"greek\">ὅσιοι</span>: Pla., Rep. 2, 363c; Orph., Hymn. 84, 3 Qu.; cf. Ps.-Pla., Axioch. 371d. Semelhantemente, os essênios são chamados <span class=\"greek\">ὅσιοι</span> em Philo, Omn. Prob. Liber 91; cf. 75 <span class=\"greek\">ὁσιότης</span>; PParis 68c, 14 <span class=\"greek\">ὅσιοι</span> <span class=\"greek\">Ἰουδαῖοι</span> (ver Dssm., B 62, 4 [BS 68, 2]); PGM 5, 417, acerca de adorador de Hermes. ⓑ Sobre Cristo, o Sumo Sacerdote celestial (com <span class=\"greek\">ἄκακος</span>; cf. a oposição em Od. 16, 423), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:26</a>. Como substantivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅσιός</span> <span class=\"greek\">σου</span>, teu Santo (segundo Ps 15:10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:27</a>; 13:35 (cf. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅσιος</span> a respeito de Abraão, Did., Gen. 228, 8). ② Relativo a ser padrão do que constitui santidade, santo, de Deus (raramente de divindades fora de nossa literatura: Orph., Hymn. 77, 2 Qu.; Arg. 27; CIG 3594; 3830). ⓐ Como adjetivo, acerca de Deus (Dt 32:4; Ps 144:17), santo: <span class=\"greek\">μόνος</span> <span class=\"greek\">ὅσιος</span>, o único santo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:4</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">παιδεία</span>, disciplina santa (isto é, divina), 1 Cl 56:16. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὁσιώτατον</span> <span class=\"greek\">ὄνομα</span>, o santíssimo nome, 58:1. ⓑ Como substantivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅσιος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:5</a>. ③ A referência a <span class=\"greek\">ὅς</span>. em <span class=\"greek\">δώσω</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅς</span>. <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πιστά</span>, «concederei a vós (plural) as garantias ou decretos divinos infalíveis relativos a Davi», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:34</a>, tem interesse especial (sobre <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅς</span>. no sentido de decretos ou ordenanças divinos, ver Wsd 6:10; Jos., Ant. 8, 115—). Essa citação de Is 55:3 evidentemente pretende mostrar que a citação de Ps 15:10, imediatamente seguinte, não poderia referir-se ao salmista Davi, mas somente a Cristo (cf. argumentação semelhante sobre um referente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a>–9). As promessas a Davi foram solenemente transferidas a «vós». Mas o próprio Davi não serviu a vós, e sim à sua geração (versículo 36). Assim, as promessas de Deus não se referem a ele, mas ao seu descendente messiânico.—Bibliografia sob <span class=\"greek\">ἅγιος</span>. JBolkestein, <span class=\"greek\">Ὅσιος</span> en <span class=\"greek\">Εὐσεβής</span>, dissertação Amsterdam ’36; WTerstegen, <span class=\"greek\">Εὐσεβής</span> en <span class=\"greek\">Ὅσιος</span> in het Grieksch taalgebruik na de 4 e eeuw, dissertação Utrecht ’41; JMontgomery, HTR 32, ’39, 97–102; MvanderValk, Z. Worte <span class=\"greek\">ὅσιος</span>: Mnemosyne 10, ’41; Dodd 62–64.—B. 1475. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁσιότης, τητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁσιότης</span>, <span class=\"greek\">τητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὅσιος</span>; X., Pla., Isocr. e outros; Epict. 3, 26, 32 <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁς</span>. [essa combinação também em Cat. Cod. Astr. V/4 181, 22]; inscrições; UPZ 33, 10 [162/161 a.C.]; 36, 13; LXX; En 102:5; EpArist 18 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁς</span>.; Philo, Abr. 208 <span class=\"greek\">ὁς</span>. <span class=\"greek\">μὲν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span>, <span class=\"greek\">δικαιοσύνη</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀνθρώπους</span>, Spec. Leg. 1, 304, Virt. 47 <span class=\"greek\">δικ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁς</span>.; Jos., Ant. 19, 300; <span class=\"greek\">δι</span>’ <span class=\"greek\">ὁσιότητα</span> <span class=\"greek\">ἀποθνῄσκειν</span>, Orig., C. Cels. 8, 54, 43), estado de atitude adequada para com Deus manifestada em ações, devoção, piedade, santidade: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">δικαιοσύνῃ</span>, em santidade e justiça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.75\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:75</a> (a combinação indica elevado grau de <span class=\"greek\">ἀρετή</span>, virtude, marca de cidadão excepcional; cf. Pla., Prot. 319c; SIG 800, 21 <span class=\"greek\">ὁσίως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δικαίως</span>, como também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:10</a>), 1 Cl 48:4. Sobre um novo ser humano, criado à semelhança de Deus: <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, em verdadeira justiça e santidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:24</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">ψυχῆς</span>, em santidade de alma, 1 Cl 29:1 (cf. Philo, Abr. 198). <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">καρδίας</span>, em santidade de coração (3 Km 9:4; Dt 9:5; Theoph. Ant. 2, 35 [p. 186, 19]), 32:4; 60:2.—DELG s.v. <span class=\"greek\">ὅσιος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁσίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁσίως</span>, advérbio de <span class=\"greek\">ὅσιος</span> (Eur., X., Pla. e posteriores; inscrições, papiros, LXX; EpArist 306; 310; Philo, Aet. M. 10 <span class=\"greek\">εὐσεβῶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὁς</span>.; Ar.; Just., A I, 21, 6 <span class=\"greek\">ὁς</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐναρέτως</span>. Com <span class=\"greek\">εὐαγῶς</span>, Orig., C. Cels. 4, 10, 3), relativo ao modo agradável a Deus, devotamente, piedosamente, 1 Cl 21:8. <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, servir a Deus, 26:1. <span class=\"greek\">ἐπικαλεῖσθαι</span> <span class=\"greek\">θεόν</span>, invocar a Deus, 60:4 (segundo as versões latina, siríaca e copta; o termo falta no único manuscrito grego que inclui essa passagem). <span class=\"greek\">θεῷ</span> <span class=\"greek\">ὁς</span>. <span class=\"greek\">εὐαρεστεῖν</span>, agradar piedosamente a Deus, 62:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> … <span class=\"greek\">ὁς</span>. <span class=\"greek\">παρέχειν</span> <span class=\"greek\">τινί</span>, manifestar amor piedosamente a alguém, 21:7. <span class=\"greek\">ὁς</span>. <span class=\"greek\">πολιτεύσασθαι</span>, comportar-se piedosamente, 6:1. Com <span class=\"greek\">δικαίως</span> (ver <span class=\"greek\">ὅσιος</span> 1a e <span class=\"greek\">δικαίως</span> 2): PtK 2 p. 15, 2; <span class=\"greek\">ἀναστρέφεσθαι</span>, conduzir-se, 2 Cl 5:6 (SIG 800, 20f <span class=\"greek\">ἀναστρέφεται</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τε</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ὁσίως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δικαίως</span> = «ele se comporta perante os deuses e todas as pessoas de modo piedoso e reto»; <span class=\"greek\">ζῆν</span>, viver, Theoph. Ant. 2, 16 [p. 140, 20]). Com <span class=\"greek\">δικ</span>. e <span class=\"greek\">ἀμέμπτως</span>: <span class=\"greek\">γενέσθαι</span>, comportar-se (cf. 1 Cl 40:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:10</a>. <span class=\"greek\">ἀμέμπτως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁς</span>., <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δῶρα</span>, apresentar ofertas irrepreensivelmente e com piedade, 1 Cl 44:4.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀσμή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀσμή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὄζω</span>; trágicos, Thu. e outros; PGM 13, 365; LXX, En; TestAbr, Test12Patr; JosAs 16:4 [<span class=\"greek\">ὀς</span>. <span class=\"greek\">ζωῆς</span>]; SibOr 3, 462; Philo; Jos., Ant. 2, 297) e <span class=\"greek\">ὀδμή</span> (Hom. e outros; prosa posterior [ver L-S-J-M s.v. <span class=\"greek\">ὀσμή</span>; Phryn. p. 89 Lob.]), em geral «odor, cheiro». ① Qualidade de algo que estimula o olfato, odor, cheiro (o termo por si só não indica se é agradável ou desagradável). ⓐ De odor agradável, perfume: de unguento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a> (cf. Achilles Tat. 2, 38, 3 <span class=\"greek\">ὀσμή</span>, sobre o perfume de unguento, e Plut., Alex. 676 [20, 13] <span class=\"greek\">ὀδώδει</span> <span class=\"greek\">ὐπ</span>’ <span class=\"greek\">ἀρωμάτων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μύρων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span>). ⓑ De odor desagradável, mau cheiro, fedor (Tob 6:17 S; 8:3; Job 6:7), Papias (3:3 <span class=\"greek\">ὀδμή</span>). ② Qualidade de algo que afeta a mente como se fosse um cheiro, odor, extensão figurada de 1 (Sir 24:15, sobre a Sabedoria; Porphyr., Adv. Christ. [ABA 1916] 69, 20, menciona <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λέξεως</span>, o [mau] cheiro [<span class=\"greek\">ὀσμή</span> = fedor; ver Artem. abaixo] do dito de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:53</a>): <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">αὐτοῦ</span>, o perfume do conhecimento dele (= de Deus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:14</a>. Esse perfume espalha-se pelo mundo através da pregação e das obras apostólicas: <span class=\"greek\">οἷς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, <span class=\"greek\">οἷς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωήν</span>, para uns, odor de morte para morte; para outros, de vida para vida, versículo 16 (JosAs 16:4 <span class=\"greek\">ὀς</span>. <span class=\"greek\">ζωῆς</span>; ver <span class=\"greek\">εὐωδία</span>). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀσμῆς</span> <span class=\"greek\">ἐλεγχθήσεσθε</span>, pelo cheiro sereis convencidos (ou examinados), quanto a terdes sido corrompidos ou não [Soph., Ant. 412, o cheiro vindo do cadáver; Artem. 1, 51 <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">ἐλέγχει</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀσμήν</span>], IMg 10:2. <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">εὐωδίας</span> (Gen 8:21; Ex 29:18; Lev 1:9, 13 e outros), oferta perfumada, figuradamente, com referência ao donativo dos filipenses, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:18</a>; ao sacrifício de Jesus por si mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:2</a>; ao coração cheio de louvor, 2:10.—ELohmeyer, Vom göttlichen Wohlgeruch: SBBerlAk IX 1919; SLilja, The Treatment of Odours in the Poetry of Antiquity ’72.—B. 1022f. Straub 41. DELG s.v. <span class=\"greek\">ὄζω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅσος, η, ον</h1><div class=\"entry-meta\"><span>pronome correlativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅσος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e posteriores), correlativo de <span class=\"greek\">πόσος</span>, <span class=\"greek\">τοσοῦτος</span> (Jos., Ant. 1, 318). ① Relativo a extensão de espaço ou de tempo igual a outra extensão da mesma ordem, tão grande quanto, tão longe quanto, durante tanto tempo quanto. ⓐ De espaço: <span class=\"greek\">τὸ</span> <span class=\"greek\">μῆκος</span> <span class=\"greek\">αὐτῆς</span> (<span class=\"greek\">τοσοῦτόν</span> <span class=\"greek\">ἐστιν</span>), <span class=\"greek\">ὅσον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλάτος</span>, seu comprimento é tão grande quanto a largura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a>.—<span class=\"greek\">ὅσον</span> <span class=\"greek\">ὅσον</span>, pequena distância (sobre a duplicação de <span class=\"greek\">ὅσον</span>, ver Aristoph., Vesp. 213; Leonidas: Anth. Pal. 7, 472, 3; Hesych. 1421), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:3</a> D. ⓑ De tempo: <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅς</span>. <span class=\"greek\">χρόνον</span>, durante todo o tempo em que (UPZ 160, 12 [119 a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a>. Também <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span> (X., Cyr. 5, 5, 8; Polyaenus 4, 7, 10; UPZ 162 I, 23 [117 a.C.]; Jos., Ant. 13, 359), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:13</a>. <span class=\"greek\">ὅς</span>. <span class=\"greek\">χρόνον</span> (X., Cyr. 5, 3, 25; Josh 4:14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:19</a>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">ὅσον</span> <span class=\"greek\">ὅσον</span> (B-D-F § 304; Rob. 733; JWackernagel, Glotta 4, 1913, 244f; OLagercrantz, Eranos 18, 1918, 53ff), dentro de muito pouco tempo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:37</a>; 1 Cl 50:4 (ambos segundo Is 26:20).—<span class=\"greek\">ἐν</span> <span class=\"greek\">ὅσῳ</span> (Aristoph., Pax 943; Thu. 8, 87, 4), enquanto, Dg 8:10. ② Relativo à quantidade ou número comparativo de objetos ou acontecimentos, quanto(s), tanto(s) quanto (Aelian, VH 1, 4): <span class=\"greek\">ὅσον</span> <span class=\"greek\">ἤθελον</span>, tanto quanto queriam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:11</a> (Appian, Bell. Civ. 4, 11 §173 <span class=\"greek\">ὅσον</span> <span class=\"greek\">ἐβούλετο</span>; Just., A I, 45, 1 <span class=\"greek\">ὅσα</span> <span class=\"greek\">βούλει</span> <span class=\"greek\">ἐξέταζε</span>).—Com <span class=\"greek\">πάντες</span> (<span class=\"greek\">ἅπαντες</span>), todos os que (Jos., Ant. 18, 370; Just., D. 11, 2): <span class=\"greek\">ἅπαντες</span> <span class=\"greek\">ὅσοι</span>, todos quantos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:24</a>; 5:36f. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span>, todas as coisas que (Job 1:12; GrBar 7:2; Philo, Op. M. 40; Jos., Ant. 10, 35), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; 13:46; 18:25; 28:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:30a</a>; 11:24; 12:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:12</a>, 22.—Mesmo sem <span class=\"greek\">πάντες</span> / <span class=\"greek\">πάντα</span>, <span class=\"greek\">ὅσοι</span> / <span class=\"greek\">ὅσα</span> pode significar tudo quanto (Polyaenus 17, 15, 2; Jos., Ant. 12, 399; Just., D. 26, 1; 87, 4): <span class=\"greek\">οἱ</span> <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">ὅσοι</span> <span class=\"greek\">συνῆλθαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Πέτρῳ</span>, todos os fiéis que vieram com Pedro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:45</a>. <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">ὅσα</span>, todas as vestes que, 9:39. <span class=\"greek\">ὅσα</span> <span class=\"greek\">κακὰ</span> <span class=\"greek\">ἐποίησεν</span>, todo o mal que praticou, versículo 13. <span class=\"greek\">ὅσα</span> <span class=\"greek\">εἶδες</span> <span class=\"greek\">παράδοξα</span>, todas as coisas extraordinárias que viste, GJs 20:4. <span class=\"greek\">ὅσοι</span> …, <span class=\"greek\">αὐτοῖς</span>, todos os que …, a eles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:12</a>. <span class=\"greek\">ὅσοι</span> …, <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:16</a>. <span class=\"greek\">ὅσοι</span> …, <span class=\"greek\">οὗτοι</span>, todos os que …, estes (Herm. Wr. 4, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:12</a>. <span class=\"greek\">ὅσα</span> …, <span class=\"greek\">ταῦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:8</a> (sobre as seis repetições de <span class=\"greek\">ὅσα</span>, cf. Liban., Or. 20 p. 443, 1, onde <span class=\"greek\">ὅσοι</span> se repete três vezes; também Appian, Liby. 117 §554 <span class=\"greek\">ὅσα</span> <span class=\"greek\">περιττὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μάταια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τρυφερὰ</span> <span class=\"greek\">ἦν</span>). Com <span class=\"greek\">οὗτοι</span> antecedente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:15</a>.—Absolutamente <span class=\"greek\">ὅσοι</span> (cf. Pla., Rep. 3, 415a), todos aqueles que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:6</a>, 34; 13:48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:12ab</a>; 6:3 e outros. <span class=\"greek\">ὅσα</span>, tudo quanto, qualquer coisa que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:8</a>; 5:19f; 9:13; 10:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:23</a>; 8:39ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:18</a> e outros. Com <span class=\"greek\">ἄν</span> (<span class=\"greek\">ἐάν</span>), tornando a expressão mais geral, todos aqueles que, quem quer que, literalmente «tantos quantos» (papiros, LXX): <span class=\"greek\">ὅσοι</span> com indicativo seguinte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:56</a>; com subjuntivo seguinte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:39</a>. <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐάν</span> (PGM 12, 71 <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">θέλω</span>; Mel., P. 35, 237 <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">γίνεται</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:18ab</a>, ou <span class=\"greek\">ἄν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:22</a>. Igualmente <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐάν</span> (ou <span class=\"greek\">ἄν</span>) com subjuntivo seguinte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; 21:22; 23:3 (sobre isso, ver HGrimme, BZ 23, ’35, 171–79); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:22</a>. ③ Relativo ao grau de extensão correlativa: <span class=\"greek\">ὅσον</span> …, <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">περισσότερον</span>, quanto mais … tanto mais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:36</a>; cf. Hs 9, 1, 8. <span class=\"greek\">ὅσον</span> …, <span class=\"greek\">πλειόνως</span>, quanto mais … tanto mais, IEph 6:1. <span class=\"greek\">πλείονος</span> …, <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> <span class=\"greek\">πλείονα</span>, tanto mais … quanto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:3</a>. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> …, <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοσοῦτο</span>, na medida em que … na mesma medida, 7:20, 22. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> …, <span class=\"greek\">οὕτως</span>, assim como … assim, 9:27f. <span class=\"greek\">τοσούτῳ</span> …, <span class=\"greek\">ὅσῳ</span>, tanto … quanto, 1:4. <span class=\"greek\">τοσούτῳ</span> <span class=\"greek\">μᾶλλον</span>, <span class=\"greek\">ὅσῳ</span>, tanto mais … quanto, 10:25 (ver <span class=\"greek\">τοσοῦτος</span> 5). <span class=\"greek\">τοσοῦτόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ὠφελεῖν</span> …, <span class=\"greek\">ὅσον</span>, Papias (2:4). Sem <span class=\"greek\">τοσούτῳ</span>, na medida em que (Polyb. 4, 42, 5; Plut., Alex. M. 5, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>. <span class=\"greek\">ὅσα</span> … <span class=\"greek\">τοσοῦτον</span>, na medida em que … na mesma medida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:7</a>. <span class=\"greek\">ὅσον</span>, tanto quanto, 19:8; D 12:2. Sobre <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὅσον</span>, ver <span class=\"greek\">ἐπί</span> 13 e 18c <span class=\"greek\">β</span>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅσπερ</h1><div class=\"entry-meta\"><span>pronome</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅσπερ</span>, ver <span class=\"greek\">ὅς</span> 1j <span class=\"greek\">ε</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀστέον, ου</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀστέον</span>, <span class=\"greek\">ου</span> (Hom. e outros, novamente no período helenístico, por exemplo Plut., Pyrrh. 3, 6; PsSol; TestSol 18:35 [cf. PVindobBosw]), plural <span class=\"greek\">ὀστέα</span> (SIG 624, 7; Just., A I, 19, 1.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:39</a>); genitivo <span class=\"greek\">ὀστέων</span> (Soph., Trach. 769; Pla., Phd. 47, 98cd; Dionys. Hal. 13, 4, 4; Jos., Bell. 6, 304; Tat.).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:30</a>, variante de leitura; 1 Cl 6:3b (Gen 2:23); IRo 5:3; e forma contraída <span class=\"greek\">ὀστοῦν</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">τό</span> (ática), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:36</a> (Ex 12:46; Num 9:12); 1 Cl 6:3a (Gen 2:23). Plural <span class=\"greek\">ὀστᾶ</span> (Diod S 22, 12; Epict. 4, 7, 32; OGI 599, 1; PLond III, 1170 verso, 486 p. 204 [258/59 d.C.]; PGM 5, 460; PsSol; TestSol 18:11 P; TestJob, Test12Patr; JosAs capítulos 16 e 29, códice A; Jos., Ant. 5, 125; 8, 232; Just., D. 103, 8 <span class=\"greek\">ὀστῶν</span>; Mel., P. 12, 81), 1 Cl 18:8 (Ps 50:10); 25:3; MPol 18:2 (ver B-D-F § 45; W-S. §8, 7; Mlt-H. 121). A LXX emprega as formas contraídas no nominativo e acusativo, e as não contraídas no genitivo e dativo (Thackeray 144). Osso; entre as passagens acima, destacam-se quanto ao conteúdo: <span class=\"greek\">σὰρξ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀστέα</span>, carne e ossos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:30</a>, variante de leitura (Od. 11, 219; Epict. 4, 7, 32 <span class=\"greek\">οὐ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ὀστα</span>; Gen 29:14; Judg 9:2; 2 Km 5:1; Mi 3:2; Just., A I, 19, 1). <span class=\"greek\">σκορπισμοὶ</span> <span class=\"greek\">ὀστέων</span>, dispersão de ossos (associada à destruição violenta do corpo humano), IRo 5:3 (influenciada por Ps 21:15). <span class=\"greek\">ὀστᾶ</span> <span class=\"greek\">τεταπεινωμένα</span>, ossos quebrantados, 1 Cl 18:8 (Ps 50:10). <span class=\"greek\">τὰ</span> <span class=\"greek\">Ἐλισαίου</span> <span class=\"greek\">ὀστά</span>, os ossos de Eliseu, AcPlCor 2:32.—B. 207. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅστις, ἥτις, ὅ τι</h1><div class=\"entry-meta\"><span>pronome relativo/interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅστις</span>, <span class=\"greek\">ἥτις</span>, <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> (Hom. e posteriores.—Sobre a ortografia de <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span>, ver W-S. §5, 6; Mlt-H. 179); tanto em nossa literatura quanto nos papiros ocorre geralmente no nominativo. ① Qualquer pessoa, quem quer que, todo aquele que, em sentido generalizador. ⓐ Seguido de indicativo presente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:39</a>; 13:12ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:20</a>; 8:34, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:4</a>. Pleonasticamente <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅστις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>. ⓑ Com indicativo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7</a>; 20:4. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅστις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:29</a>. ⓒ Com indicativo futuro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:41</a>; 18:4; 23:12ab; <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅστις</span>, 10:32. ⓓ Com subjuntivo aoristo (ApcSed 16:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:33</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:10</a>. Mas ver a respeito B-D-F § 380, 4; Rob. 959; Kühner-G. II 426, 1. ⓔ Com <span class=\"greek\">ἄν</span> (<span class=\"greek\">ἐάν</span>), aumentando o caráter indefinido da expressão: <span class=\"greek\">α</span>. Com subjuntivo presente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:17</a> (<span class=\"greek\">πᾶν</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐάν</span>). <span class=\"greek\">β</span>. Com subjuntivo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:33</a> (ver d acima); 12:50; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:13</a>; 15:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:23</a>. ② Pessoa indeterminada pertencente a uma classe ou possuidora de certo estatuto, quem, alguém que. ⓐ Para indicar que pessoas (ou coisas) pertencem a determinada categoria, alguém da espécie que: <span class=\"greek\">ἡγούμενος</span>, <span class=\"greek\">ὅστις</span> <span class=\"greek\">ποιμανεῖ</span>, um governante que apascentará, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a>. <span class=\"greek\">εὐνοῦχοι</span> <span class=\"greek\">οἵτινες</span>, 19:12abc; <span class=\"greek\">γεωργοὶ</span> <span class=\"greek\">οἵτινες</span>, 21:41. <span class=\"greek\">παρθένοι</span>, <span class=\"greek\">αἵτινες</span>, 25:1. <span class=\"greek\">τινὲς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">ἑστώτων</span>, <span class=\"greek\">οἵτινες</span>, 16:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:1</a>. <span class=\"greek\">προφήτας</span>, <span class=\"greek\">οἵτινες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπλανῆ</span> <span class=\"greek\">θεοσέβειαν</span> <span class=\"greek\">ἐκήρυσσον</span>, profetas que proclamaram a devoção correta a Deus, AcPlCor 2:10. ⓑ Para salientar qualidade característica que confirma uma afirmação anterior, quem (de fato, por sua natureza), na medida em que: <span class=\"greek\">προσέχετε</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ψευδοπροφητῶν</span> <span class=\"greek\">οἵτινες</span> <span class=\"greek\">ἔρχονται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐνδύμασι</span> <span class=\"greek\">προβάτων</span>, guardai-vos dos falsos profetas, que vêm vestidos de ovelhas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:15</a>. <span class=\"greek\">βαπτισθῆναι</span> <span class=\"greek\">τούτους</span> <span class=\"greek\">οἵτινες</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἔλαβον</span>, batizar estes que (de fato) receberam o Espírito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:47</a>. <span class=\"greek\">οἵτινες</span> <span class=\"greek\">ἐδέξαντο</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, na medida em que receberam a palavra, 17:11. <span class=\"greek\">οἵτινες</span> <span class=\"greek\">μετήλλαξαν</span>, visto que, de fato, trocaram, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:25</a>; cf. versículo 32; 2:15; 6:2. <span class=\"greek\">ἀσπάσασθε</span> M <span class=\"greek\">αρίαν</span> <span class=\"greek\">ἥτις</span>, saudai Maria, que certamente, 16:6; cf. versículos 4, 7, 12. <span class=\"greek\">ψευδαδέλφους</span>, <span class=\"greek\">οἵτινες</span> <span class=\"greek\">παρεισῆλθον</span>, falsos irmãos, daqueles que se insinuaram clandestinamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:4</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a> e outras passagens paulinas (B-D-F § 293, 4; Rob. 728); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:5</a>; 10:11; 13:7; AcPlCor 2:19, 25 (condenação dos gnósticos, com exemplos de suas posições); 2:21 (advertência urgente para evitá-los). Semelhantemente, <span class=\"greek\">Ἀβραάμ</span>, <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἀπέθανεν</span>, Abraão, que morreu, como sabeis, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:53</a>. <span class=\"greek\">φονεῖς</span> <span class=\"greek\">ἐγένεσθε</span>, <span class=\"greek\">οἵτινες</span> <span class=\"greek\">ἐλάβετε</span> …, tornastes-vos assassinos, vós que, de fato, recebestes …, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.53\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:53</a>. <span class=\"greek\">σαρκικαὶ</span> <span class=\"greek\">ἐπιθυμίαι</span>, <span class=\"greek\">αἵτινες</span> <span class=\"greek\">στρατεύονται</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>, desejos carnais que guerreiam contra a alma, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:11</a>. <span class=\"greek\">οἵτινες</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔγνωσαν</span>, aqueles que, de fato, não conheceram, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:24</a>.—Todavia, muitas passagens citadas podem ser incluídas na categoria seguinte (3), e algumas das que lá se encontram talvez caibam melhor nesta (2). ③ Muito frequentemente <span class=\"greek\">ὅστις</span> substitui o relativo simples <span class=\"greek\">ὅς</span>, <span class=\"greek\">ἥ</span>, <span class=\"greek\">ὅ</span>; isso ocorre ocasionalmente no grego antigo (ver Hdt. 4, 8, 1 e outros; Thu. 6, 3, 1; Demosth. 38, 6; 17; Kühner-G. II 399f; Schwyzer II 643, bibliografia), mas mais frequentemente no grego posterior (W-S. §24, 14d; B-D-F § 293; Mlt. 91f; Rdm. 2 75; 77; 226; Psaltes, Grammatik [Byz.] 198; POxy 110, 3; PFay 108, 7 [ambos II d.C.]; Mayser II/3, 57. Sobre a LXX, ver Thackeray 192; TestJob 47:1; ParJer 7:8; Just., D. 88, 1; Tat. 41, 1), especialmente nos escritos de Lucas: para explicar uma palavra ou coisa, <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">καλεῖται</span> <span class=\"greek\">Βηθλέεμ</span>, à cidade de Davi, chamada Belém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:4</a> (Hdt. 2, 99 <span class=\"greek\">πόλιν</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">Μέμφις</span> <span class=\"greek\">καλέεται</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">χώραν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Γερας</span>. <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἀντιπέρα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Γαλιλαίας</span>, a região dos gerasenos, que fica defronte da Galileia, 8:26. <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">δύο</span> … <span class=\"greek\">οἵτινες</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἠλίας</span>, dois homens … que eram Moisés e Elias, 9:30. Cf. 12:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:2</a>, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:8</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐπαύριον</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρασκευήν</span>, no dia seguinte, que vem após a Preparação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.62\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:62</a> (POxy 110, 3 <span class=\"greek\">αὔριον</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ιε</span>´). <span class=\"greek\">τὸν</span> <span class=\"greek\">Βαραββᾶν</span> <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἦν</span> … <span class=\"greek\">βληθεὶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φυλακῇ</span>, Barrabás, que havia sido posto na prisão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:19</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">στασιαστῶν</span> <span class=\"greek\">δεδεμένος</span> <span class=\"greek\">οἵτινες</span> … <span class=\"greek\">φόνον</span> <span class=\"greek\">πεποιήκεισαν</span>, preso com os revoltosos que … haviam cometido homicídio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:7</a>. <span class=\"greek\">οἰκοδεσπότης</span> <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἐφύτευσεν</span> <span class=\"greek\">ἀμπελῶνα</span>, proprietário que plantou uma vinha, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>. <span class=\"greek\">οἰκοδεσπότης</span> <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἐξῆλθεν</span>, proprietário que saiu, 20:1. Cf. 27:55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:39</a>; 8:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:15</a>; 11:20, 28; 12:10; 13:43; 17:10; 21:4; 23:14, 21, 33; 24:1; 28:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:18</a>. <span class=\"greek\">βλέπειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐλάλει</span>, ver a voz que falava, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:12</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἔτεκεν</span>, a mulher que deu à luz, 12:13. ④ O uso de <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> como termo interrogativo no NT complica-se devido a variantes textuais (ver PKatz, TLZ 82, ’57, 114; 83, ’58, 318; B-D-F § 300). ⓐ Numa pergunta indireta (Just., D. 5, 1; 23, 2), <span class=\"greek\">λαληθήσεταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">τί</span> <span class=\"greek\">σε</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ποιεῖν</span>, ser-te-á dito o que deves fazer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:6</a>, está bem atestado, mas foi rejeitado por Blass (ver B-D-F § 300, 1), embora não por Rob. 730f. ⓑ Numa pergunta direta (também escrito <span class=\"greek\">ὅτι</span> na scriptio continua: ver as variantes de leitura, originalmente talvez glosas que marcavam a pergunta, Ath. 34, 1 <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">εἴποιμι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀπόρρητα</span>; sobre a LXX, ver B-D-F § 300, 2): <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">λαλεῖ</span>;, por que esse homem fala assim?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:7</a>, variante de leitura. <span class=\"greek\">ὅτι</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τελωνῶν</span> … <span class=\"greek\">ἐσθίει</span>;, por que (Jesus) come com os publicanos?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:16b</a> (variantes <span class=\"greek\">τί</span> <span class=\"greek\">ὅτι</span>, <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> ou <span class=\"greek\">διατί</span>); 9:11a, 28; <span class=\"greek\">ὅτι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔριον</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ξύλον</span>;, por que a lã sobre a madeira?, 8:5; <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">πάντες</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μετενόσαν</span>;, por que, então, … nem todos se arrependeram?, Hs 8, 6, 2 (sobre o debate dessas passagens, ver B-D-F § 300, 2; também Field, Notes 33; Mlt-Turner 49; MBlack, An Aramaic Approach 3, ’67, 119–212.—<span class=\"greek\">ὅτι</span> = «por que» em perguntas indiretas: Thu. 1, 90, 5; Jos., Ant. 6, 236; 12, 213; Gen 18:13 A; Black, 119, cita Turner, JTS 27, 1925, 58ff, em apoio desse uso em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:16f</a>; 14:60, variante de leitura; cf. B-D-F § 300, 2). ⑤ Sobre <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λαλῶ</span> <span class=\"greek\">ὑμῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:25</a>, ver <span class=\"greek\">ἀρχή</span> 1a, final.—B-D-F § 300, 2; Rob. 730. ⑥ As locuções prepositivas <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὅτου</span> (Diod S 2, 31, 9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:25</a> D; <span class=\"greek\">ἕως</span> <span class=\"greek\">ὅτου</span> (ver <span class=\"greek\">ἕως</span> 1b <span class=\"greek\">β</span> <span class=\"hebrew\" dir=\"rtl\">ב</span>; PGen 56, 19), e <span class=\"greek\">μέχρις</span> <span class=\"greek\">ὅτου</span> (<span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅτου</span>, «desde então», Just., D. 52, 3; ver <span class=\"greek\">μέχρι</span> 2b) são expressões fixas.—HCadbury, The Relative Pronouns in Acts and Elsewhere: JBL 42, 1923, 150ff; Rydbeck, 98–118.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀστράκινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀστράκινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὄστρακον</span>; Hippocr. e outros; PLond III, 1177, 75; 92 p. 183 [113 d.C.]; POxy 1648, 63; LXX; En 99:7; GrBar 3:7), feito de terra ou argila; com <span class=\"greek\">σκεῦος</span> (PLond I, 77, 22 p. 233 [VIII d.C.]; Lev 6:21; 11:33 e outros; cf. Epict. 3, 9, 18), vasos de barro (em contraste com os feitos de outros materiais), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a>. Em figura, indicando fragilidade: <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θησαυρὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀς</span>. <span class=\"greek\">σκεύεσιν</span>, ter o tesouro em vasos de barro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:7</a> (cf. Artem. 5, 25 <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀστρακίνῳ</span> <span class=\"greek\">σκεύει</span>).—Sobre imagens cultuais feitas de argila: <span class=\"greek\">θεοὶ</span> … <span class=\"greek\">ὀστράκινοι</span>, deuses … feitos de barro, Dg 2:7 (SibOr 5, 495; cf. En 99:7).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄστρακον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄστρακον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom. Hymns e outros; SIG 1168, 82; 86 [IV a.C.]; POxy 234 II, 3; 1450, 4; O. Wilck II, 1152, 5; LXX; JosAs 13:8; Philo, Somn. 2, 57; Ar. 4, 3), argila cozida, cerâmica, acerca das divindades dos politeístas: <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὄστρακον</span>, outro é um pedaço de cerâmica, Dg 2:2. Coletivamente: <span class=\"greek\">ὄς</span>. <span class=\"greek\">λεπτόν</span>, pequenos cacos de cerâmica quebrada, Hs 9, 10, 1 (diferentemente EGoodspeed, JBL 73, ’54, 85f).—DELG. M-M s.v. <span class=\"greek\">ὀστράκινος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄσφρησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄσφρησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span>, olfato, sentido do cheiro (de <span class=\"greek\">ὀσφραίνομαι</span>, «sentir o cheiro de, farejar»; Pla., Phd. 111b e outros; Philo; TestReub 2:5), ou órgão olfativo, nariz (singular em Ptolem., Apotel. 3, 15, 5; M. Ant 10, 35, 2, com <span class=\"greek\">ἀκοή</span> = «ouvido»; Diog. L. 6, 39, como dito de Diógenes, o Cínico; PRyl. 63, 5 [III d.C.] <span class=\"greek\">γλῶσσα</span> <span class=\"greek\">ὄσφρησις</span> <span class=\"greek\">ἀκοή</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:17</a> (<span class=\"greek\">ἀκοή</span> 3).—B. 1022f. DELG s.v. <span class=\"greek\">ὀσφραίνομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀσφῦς</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀσφῦς</span> (nominativo não empregado no NT; acusativo -<span class=\"greek\">ύν</span> em todas as edições. Sobre o acento, ver PKatz, TLZ 83, ’58, 315: <span class=\"greek\">ὀσφῦν</span>; B-D-F § 13; Mlt-H. 141f), <span class=\"greek\">ύος</span>, <span class=\"greek\">ἡ</span> (Aeschyl., Hdt. e posteriores; inscrições, papiros, LXX; PsSol 8:4; TestSol 1, 12 D; TestJob; TestNapht 2:8; JosAs; GrBar 2:3; Jos., Ant. 8, 217 = 3 Km 12:10). ① Lugar em que se usa cinto ou cinturão, cintura, lombos (4 Km 1:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:6</a>. Como a roupa era usada solta em casa, cingir-se indica preparação para atividade, especialmente viagem; frequentemente em imagem: <span class=\"greek\">περιζώννυσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀς</span>., cingir um cinto ao redor da cintura (Jer 1:17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:35</a> (cf. Ex 12:11). Também <span class=\"greek\">ἀναζώννυσθαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὀς</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:13</a>, em que o genitivo <span class=\"greek\">τῆς</span> <span class=\"greek\">διανοίας</span> demonstra o uso figurado extraordinário da expressão. Falta o genitivo em Pol 2:1. ② Lugar dos órgãos reprodutivos, lombos, conforme a expressão hebraica <span class=\"hebrew\" dir=\"rtl\">יָצָא</span> <span class=\"hebrew\" dir=\"rtl\">מֵחֲלָצֵי</span> <span class=\"hebrew\" dir=\"rtl\">פ׳</span> (cf. Gen 35:11; 2 Ch 6:9), como em: <span class=\"greek\">ἐξέρχεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀς</span>. <span class=\"greek\">τινός</span>, sair dos lombos de alguém = ser filho ou descendente de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀς</span>. <span class=\"greek\">τινὸς</span> <span class=\"greek\">εἶναι</span>, estar nos lombos de alguém, versículo 10. <span class=\"greek\">καρπὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀς</span>. <span class=\"greek\">τινός</span>, fruto dos lombos de alguém = descendentes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a>; AcPl Ha 8, 14 (<span class=\"greek\">ἰσχύος</span>, Ox 1602 anverso, 12f; cf. Ps 131:11, variante de leitura [ARahlfs, Psalmi cum Odis ’31].—<span class=\"greek\">καρπὸς</span> <span class=\"greek\">ὀσφύος</span> também Theodor. Prodr. 6, 370 H. Cf. Psellus p. 61, 33 <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείου</span> <span class=\"greek\">ὀσφύος</span> = «de descendência real»). Os lombos provavelmente também são considerados fonte íntima de poder em <span class=\"greek\">αἱ</span> <span class=\"greek\">ὀς</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐκλυέσθωσαν</span>, não deixeis que vossos lombos percam a força, D 16:1 (cf. TestNapht 2:8 <span class=\"greek\">ὀσφ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἰσχύν</span>).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0260-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅταν</h1><div class=\"entry-meta\"><span>partícula temporal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅταν</span>, partícula temporal (desde Hom., que, porém, sempre a separa [<span class=\"greek\">ὅτ</span>’ <span class=\"greek\">ἄν</span>]; inscrições, papiros, LXX, pseudoepígrafos, Philo, Joseph., apologistas). ① Relativo a uma ação condicional, possível e, em muitos casos, repetida, no momento em que, sempre que, quando. ⓐ Com subjuntivo, caso em que <span class=\"greek\">ὅτ</span>. frequentemente se aproxima do sentido de <span class=\"greek\">ἐάν</span>, pois a referência temporal também indica as condições em que ocorre a ação da oração principal (Kühner-G. II 447f). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:28</a>, os manuscritos variam entre <span class=\"greek\">ὅτ</span>. e <span class=\"greek\">ἐάν</span> (assim também, por exemplo, Judg 6:3). <span class=\"greek\">α</span>. Com subjuntivo presente, quando a ação da oração subordinada é contemporânea da principal. Normalmente acerca de ação (regularmente) repetida: sempre que, todas as vezes que (PFay 109, 1 <span class=\"greek\">ὅταν</span> <span class=\"greek\">θέλῃς</span> = «todas as vezes que quiseres»; semelhantemente POxy 1676, 26; Just., D. 128, 3 <span class=\"greek\">ὅταν</span> <span class=\"greek\">βούληται</span>. Cf. <span class=\"greek\">ἄν</span> I, c <span class=\"greek\">α</span>): <span class=\"greek\">ὅταν</span> <span class=\"greek\">ποιῇς</span> <span class=\"greek\">ἐλεημοσύνην</span>, sempre que deres esmola, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:2</a>; cf. 5f, 16; 10:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:11</a>. <span class=\"greek\">ὅταν</span> <span class=\"greek\">θέλητε</span>, quando quiserdes, 14:7.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:11</a>; 14:12f e outros. Com <span class=\"greek\">τότε</span> em seguida, sempre que …, então (Hero Alex. III p. 214, 5): <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἀσθενῶ</span>, <span class=\"greek\">τότε</span> <span class=\"greek\">δυνατός</span> <span class=\"greek\">εἰμι</span>, quando sou fraco, então sou forte, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:10</a>. Também sem a ideia de repetição, quando, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:3</a>.—Retomando referência temporal precedente: <span class=\"greek\">ἕως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἐκείνης</span> <span class=\"greek\">ὅταν</span> <span class=\"greek\">πίνω</span>, até aquele dia em que eu beber, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:25</a>. Introduzindo enunciado explicativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:2</a> (B-D-F § 394). <span class=\"greek\">β</span>. Com subjuntivo aoristo, quando a ação da subordinada precede a da oração principal (IMaronIsis 9 [<span class=\"greek\">ὅτ</span>]<span class=\"greek\">αν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">ἔβλεψα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span> = «sempre que com aquilo [olhos] vi o sol» [restituição corrigida da editio princeps]; PLips 104, 16 [96/95 a.C.]; PRyl 233, 2; Is 28:19; 57:13; Ath. 1, 4): <span class=\"greek\">ὅταν</span> <span class=\"greek\">ὀνειδίσωσιν</span>, quando (vos) tiverem injuriado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:11</a>. Cf. 12:43 (ver KBeyer, Semitische Syntax im NT, ’62, 285f); 13:32; 23:15; 24:32f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:15f</a>, 31f; 13:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:22</a>, 26 e frequentemente. Com <span class=\"greek\">τότε</span> em seguida, quando (algo tiver acontecido), então (Sir 18:7; Jos., Bell. 6, 287, Ant. 10, 213; TestJob 38:3; ApcEsdr 3:13 p. 27, 24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:15f</a>; 25:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:35</a> (diferentemente nas paralelas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:20</a>, em que <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ὅταν</span>, dias em que, formam unidade e <span class=\"greek\">τότε</span> se relaciona com <span class=\"greek\">καί</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:28</a>, 54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:4</a>. ⓑ Com indicativo (sobre esse desenvolvimento tardio, ver B-D-F § 382, 4; Rob. 972f; também Schwyzer II 304). <span class=\"greek\">α</span>. Com indicativo futuro (1 Km 10:7; SibOr 4, 70; 11, 219), quando, 2 Cl 12:2 (GEg 252, 57 apresenta subjuntivo aoristo na passagem correspondente); 17:6; 15:5 (ver Reinhold 108 e 2 abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:28</a>, variante de leitura (por <span class=\"greek\">ὄψησθε</span>). Sempre que, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:9</a> (Mussies 343–47). <span class=\"greek\">β</span>. Com indicativo presente (Strabo 12, 27 p. 555 <span class=\"greek\">ὅταν</span> <span class=\"greek\">δείκνυται</span>; Ps.-Lucian, Philop. 26; PHamb 70, 19 <span class=\"greek\">ὅταν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">δίδομεν</span>; Ps 47:4, variante de leitura [ARahlfs, Psalmi cum Odis ’31]; Philo, Poster. Cai. 15, variante de leitura.—ADebrunner, Glotta 11, 1920, 26f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:25</a> (além de <span class=\"greek\">στήκετε</span>, os manuscritos também apresentam <span class=\"greek\">στήκητε</span> e <span class=\"greek\">στῆτε</span>). Como variante em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:27</a>. <span class=\"greek\">γ</span>. Com indicativo imperfeito (Polyb. 4, 32, 5f <span class=\"greek\">ὅταν</span> … <span class=\"greek\">ἦσαν</span>; inscrição em CB I/2, 477 nº 343, 8; Gen 38:9; 1 Km 17:34; Ps 119:7; Da 3:7 Theod., variante de leitura; ParJer 2:3): <span class=\"greek\">ὅταν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐθεώρουν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:11</a>. <span class=\"greek\">δ</span>. Com indicativo aoristo, em lugar de <span class=\"greek\">ὅτε</span>, quando (Ex 16:3; Ps 118:32; GrBar 4:11; 8:1; ApcMos 17:37), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:1</a> (variante <span class=\"greek\">ὅτε</span>); sempre que (Ex 17:11; Num 11:9): <span class=\"greek\">ὅταν</span> <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">ἐγένετο</span>, <span class=\"greek\">ἐξεπορεύοντο</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, quando anoitecia, saíam da cidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:19</a> (ver B-D-F § 367; diferentemente Mlt. 248); Hs 9, 4, 5; 9, 17, 3. <span class=\"greek\">ε</span>. Com indicativo mais-que-perfeito, assim que, Hs 9, 1, 6. ② Marcador de ponto temporal simultâneo a uma ação com força causal, visto que: <span class=\"greek\">ὅταν</span> <span class=\"greek\">βλέπετε</span>, uma vez que vedes, 4:14 (ver Reinhold 108f).—M-M.</p></section></article>"};
